1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which instantiations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. A handle is also what tells one instantiation from
9	//! another while a type is being expanded (`Box<Box<string>>` is two instantiations of one declaration): only its
10	//! equality is read, inside one conversion, so the answer does not depend on the numbers. The recursion marker that
11	//! results is named by the declaration (the alias or interface) and holds no handle. The memo is keyed by the enclosing
12	//! instantiations a conversion actually asked about, not by all of them (see [`State::memo`]).
13	//!
14	//! Every descent into the parts of a type (members, properties, elements, holes) passes [`Converter::enter`], which
15	//! decides before anything is fetched or converted whether the type is an enclosing instantiation (a back-reference),
16	//! sits too deep, or is too wide.
17	//!
18	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
19	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
20	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
21	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type. A dependency's
22	//! union of literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
23	//! [`PropType::Truncated`], never the checker's text standing in as a name.
24	
25	use std::future::Future;
26	use std::pin::Pin;
27	use std::sync::atomic::{AtomicU64, Ordering};
28	use std::sync::{Arc, Mutex};
29	
30	use caliper_docgen_core::types::semantic::{degraded_type, unresolved_type};
31	use caliper_docgen_core::types::{
32	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
33	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
34	};
35	use rustc_hash::FxHashMap;
36	
37	use crate::printed::{Marker, SignatureMarkers, signature_markers, tuple_labels};
38	use crate::rpc::{
39	    CallError, CompactSymbol, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, TypeInfo, flag,
40	};
41	
42	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
43	const MAX_DEPTH: u8 = 5;
44	/// The most properties an object type lists at the top (a prop's own type) and below it.
45	const MAX_FIELDS: [usize; 2] = [100, 40];
46	/// The most members a union or intersection lists at the top and below it.
47	const MAX_MEMBERS: [usize; 2] = [500, 120];
48	
49	/// What a descent found at [`Converter::enter`].
50	enum Gate<T> {
51	    /// The type is not expanded: it is a back-reference, or a cap cut it.
52	    Stop(PropType),
53	    /// The parts of the type, and the context to convert them in.
54	    Open { parts: T, inner: Cx },
55	}
56	
57	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
58	
59	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
60	/// checker's type handle) enclose it, outermost first.
61	#[derive(Debug, Clone, Default)]
62	pub(crate) struct Cx {
63	    depth: u8,
64	    enclosing: Arc<Vec<u64>>,
65	    /// The conversion this context belongs to, which records which enclosing instantiations it asks about. `None` at
66	    /// the roots.
67	    frame: Option<Arc<Frame>>,
68	}
69	
70	/// What one conversion has asked of the instantiations enclosing it, kept to build its memo entry (see
71	/// [`State::memo`]).
72	#[derive(Debug)]
73	struct Frame {
74	    /// How many instantiations enclosed the type when its conversion began: those below this are the outer context, the
75	    /// rest were opened by the conversion itself.
76	    base: usize,
77	    asked: Mutex<Asked>,
78	}
79	
80	#[derive(Debug, Default)]
81	struct Asked {
82	    /// The handles this conversion's own gate compared against its enclosing instantiations.
83	    ids: Vec<u64>,
84	    /// The sets asked by the conversions of its parts, each with the instantiations this conversion had opened by then:
85	    /// those were answered inside it and do not depend on its outer context.
86	    parts: Vec<(Arc<[u64]>, Vec<u64>)>,
87	}
88	
89	impl Frame {
90	    fn new(base: usize) -> Self {
91	        Frame { base, asked: Mutex::default() }
92	    }
93	
94	    fn lock(&self) -> std::sync::MutexGuard<'_, Asked> {
95	        self.asked.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
96	    }
97	
98	    fn ask(&self, id: u64) {
99	        self.lock().ids.push(id);
100	    }
101	
102	    /// A part of this conversion was converted (or recalled) under `enclosing`, having asked about `asked`.
103	    fn absorb(&self, asked: &Arc<[u64]>, enclosing: &[u64]) {
104	        if !asked.is_empty() {
105	            self.lock().parts.push((asked.clone(), enclosing.get(self.base..).unwrap_or_default().to_vec()));
106	        }
107	    }
108	
109	    /// Every handle the conversion asked about whose answer came from outside it: sorted, once each.
110	    fn finish(&self) -> Arc<[u64]> {
111	        let asked = self.lock();
112	        let mut ids = asked.ids.clone();
113	        for (part, opened) in &asked.parts {
114	            ids.extend(part.iter().copied().filter(|id| !opened.contains(id)));
115	        }
116	        ids.sort_unstable();
117	        ids.dedup();
118	        ids.into()
119	    }
120	}
121	
122	impl Cx {
123	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
124	    /// and passes [`Converter::enter`] if it has parts.
125	    fn argument(&self) -> Cx {
126	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone(), frame: self.frame.clone() }
127	    }
128	
129	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
130	    /// only a name can be pointed back to.
131	    fn below(&self, instance: Option<u64>) -> Cx {
132	        let mut enclosing = self.enclosing.clone();
133	        if let Some(id) = instance
134	            && !enclosing.contains(&id)
135	        {
136	            let mut grown = (*enclosing).clone();
137	            grown.push(id);
138	            enclosing = Arc::new(grown);
139	        }
140	        Cx { depth: self.depth.saturating_add(1), enclosing, frame: self.frame.clone() }
141	    }
142	
143	    /// Whether `id` is an instantiation being expanded around the type. The conversion in progress is recorded to have
144	    /// asked, whichever the answer.
145	    fn encloses(&self, id: u64) -> bool {
146	        if let Some(frame) = &self.frame {
147	            frame.ask(id);
148	        }
149	        self.enclosing.contains(&id)
150	    }
151	
152	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
153	        limits[usize::from(self.depth > 0).min(N - 1)]
154	    }
155	}
156	
157	/// What declares a type: the alias it was written through, else its interface or class.
158	#[derive(Debug, Clone)]
159	struct Origin {
160	    name: String,
161	    /// The declaring file as the checker keys it (lower-cased path).
162	    file: String,
163	    alias: bool,
164	}
165	
166	impl Origin {
167	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
168	        let declaration = symbol.declarations.first().map(String::as_str);
169	        Origin {
170	            name: symbol.name.clone(),
171	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
172	            alias,
173	        }
174	    }
175	
176	    fn in_dependency(&self) -> bool {
177	        self.file.contains("/node_modules/")
178	    }
179	
180	    fn in_lib(&self) -> bool {
181	        let name = self.file.rsplit('/').next().unwrap_or("");
182	        name.starts_with("lib.") && name.ends_with(".d.ts")
183	    }
184	
185	    fn in_react(&self) -> bool {
186	        self.file.contains("/@types/react/")
187	    }
188	
189	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
190	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
191	    fn is_boundary(&self) -> bool {
192	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
193	        if self.in_lib() { !self.alias } else { self.in_dependency() }
194	    }
195	
196	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
197	    fn react_terminal(&self) -> Option<PropType> {
198	        if !self.in_react() {
199	            return None;
200	        }
201	        match (self.name.as_str(), self.alias) {
202	            ("ReactNode", true) | ("ReactElement" | "Element", false) => Some(PropType::ReactNode),
203	            ("ElementType", true) => Some(PropType::ElementType),
204	            ("CSSProperties", false) => Some(PropType::CssProperties),
205	            _ => None,
206	        }
207	    }
208	}
209	
210	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
211	pub(crate) fn declared_in(declaration: &str) -> &str {
212	    declaration.splitn(3, '.').nth(2).unwrap_or("")
213	}
214	
215	/// A converted type, with the enclosing instantiations its conversion depended on.
216	#[derive(Debug)]
217	struct Entry {
218	    /// Every handle the conversion compared against the instantiations enclosing it, sorted.
219	    asked: Arc<[u64]>,
220	    /// Those of `asked` that did enclose it.
221	    enclosed_by: Vec<u64>,
222	    converted: PropType,
223	}
224	
225	impl Entry {
226	    /// Whether the conversion would go the same way inside `enclosing`: among the handles it asked about, the ones
227	    /// that enclose the type there are exactly `enclosed_by`.
228	    fn holds_in(&self, enclosing: &[u64]) -> bool {
229	        self.enclosed_by.iter().all(|id| enclosing.contains(id))
230	            && enclosing.iter().all(|id| self.enclosed_by.contains(id) || self.asked.binary_search(id).is_err())
231	    }
232	}
233	
234	type Memo = Mutex<FxHashMap<(u64, u8), Vec<Arc<Entry>>>>;
235	
236	#[derive(Default)]
237	struct State {
238	    /// Conversions by (type handle, depth), each entry with the enclosing instantiations it depended on. The handles
239	    /// are valid inside this snapshot only.
240	    ///
241	    /// Why an entry may be reused where [`Entry::holds_in`] says. A conversion reads its context in two ways only: the
242	    /// depth, which is in the key, and [`Cx::encloses`], the question whether a handle is an instantiation being
243	    /// expanded around the type. Everything else it reads is the checker's answer about the type, which does not change
244	    /// inside a snapshot. So a conversion is a deterministic walk whose every step is fixed by the type, the depth and
245	    /// the answers to those questions, in the order they are asked. Run it again where each handle it asked about has
246	    /// the same answer, and it asks the same questions in the same order and returns the same type. A handle that the
247	    /// conversion opened itself is settled inside it (it was found not to enclose the type at its own gate, which is
248	    /// recorded), so only the handles asked of the outer context are kept. A type in no cycle with its context asks
249	    /// nothing that encloses it and holds everywhere; one in a cycle holds where the same part of the cycle encloses
250	    /// it. Entries that hold in a context all agree, so which of them is found first, and so the order in which
251	    /// types were first reached, cannot show in the output.
252	    memo: Memo,
253	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
254	    /// By (type handle, whether printed expanded: see [`Rpc::type_to_string_expanded`]).
255	    printed: Mutex<FxHashMap<(u64, bool), String>>,
256	    hits: AtomicU64,
257	    misses: AtomicU64,
258	}
259	
260	#[derive(Clone)]
261	pub(crate) struct Converter {
262	    rpc: Arc<Rpc>,
263	    state: Arc<State>,
264	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
265	    reverse: bool,
266	}
267	
268	impl Converter {
269	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
270	        Self { rpc, state: Arc::new(State::default()), reverse }
271	    }
272	
273	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
274	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
275	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
276	        let order: Box<dyn Iterator<Item = usize> + Send> =
277	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
278	        for index in order {
279	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
280	                *slot = Some(self.convert(info, cx).await?);
281	            }
282	        }
283	        Ok(slots.into_iter().flatten().collect())
284	    }
285	
286	    /// Memo hits and misses so far, for the debug line.
287	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
288	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
289	    }
290	
291	    /// The own types of a component's props, from the top.
292	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
293	        self.convert_all(infos, &Cx::default()).await
294	    }
295	
296	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
297	        Box::pin(async move {
298	            if let Some(entry) = self.recall(info.id, cx) {
299	                self.state.hits.fetch_add(1, Ordering::Relaxed);
300	                if let Some(frame) = &cx.frame {
301	                    frame.absorb(&entry.asked, &cx.enclosing);
302	                }
303	                return Ok(entry.converted.clone());
304	            }
305	            self.state.misses.fetch_add(1, Ordering::Relaxed);
306	            let frame = Arc::new(Frame::new(cx.enclosing.len()));
307	            let own = Cx { depth: cx.depth, enclosing: cx.enclosing.clone(), frame: Some(frame.clone()) };
308	            let converted = self.uncached(info, &own).await?;
309	            let asked = frame.finish();
310	            if let Some(parent) = &cx.frame {
311	                parent.absorb(&asked, &cx.enclosing);
312	            }
313	            let enclosed_by = cx.enclosing.iter().copied().filter(|id| asked.binary_search(id).is_ok()).collect();
314	            let entry = Arc::new(Entry { asked, enclosed_by, converted: converted.clone() });
315	            if let Ok(mut memo) = self.state.memo.lock() {
316	                memo.entry((info.id, cx.depth)).or_default().push(entry);
317	            }
318	            Ok(converted)
319	        })
320	    }
321	
322	    /// The entry for the type at this depth that holds inside the instantiations enclosing it, if there is one.
323	    fn recall(&self, id: u64, cx: &Cx) -> Option<Arc<Entry>> {
324	        let memo = self.state.memo.lock().ok()?;
325	        memo.get(&(id, cx.depth))?.iter().find(|entry| entry.holds_in(&cx.enclosing)).cloned()
326	    }
327	
328	    async fn uncached(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
329	        if info.is_error() {
330	            return Ok(unresolved_type(self.display(info.id).await?));
331	        }
332	        if let Some(simple) = simple(info) {
333	            return Ok(simple);
334	        }
335	        let flags = info.flags;
336	        if flags & flag::TYPE_PARAMETER != 0 {
337	            return self.type_parameter(info).await;
338	        }
339	        if flags & (flag::STRING_LITERAL | flag::NUMBER_LITERAL | flag::BIG_INT_LITERAL) != 0 {
340	            return self.literal(info).await;
341	        }
342	        if flags & flag::BOOLEAN_LITERAL != 0 {
343	            return Ok(PropType::BoolLiteral(self.boolean_value(info).await?));
344	        }
345	        if flags & flag::UNIQUE_ES_SYMBOL != 0 {
346	            let name = self.rpc.symbol_of_type(info.id).await?.map(|symbol| symbol.name);
347	            return Ok(match name {
348	                Some(name) => PropType::UniqueSymbol { name: name.into() },
349	                None => named(self.display(info.id).await?, Vec::new()),
350	            });
351	        }
352	        if flags & flag::TEMPLATE_LITERAL != 0 {
353	            return self.template(info, cx).await;
354	        }
355	        // `Uppercase<string>` and its siblings: a name, since there is no shape to expand.
356	        if flags & flag::STRING_MAPPING != 0 {
357	            return Ok(named(self.display(info.id).await?, Vec::new()));
358	        }
359	        // Types the checker could not resolve because a type parameter is still open.
360	        if flags & (flag::CONDITIONAL | flag::INDEXED_ACCESS | flag::INDEX | flag::SUBSTITUTION) != 0 {
361	            let text = self.display(info.id).await?;
362	            let reason = if flags & flag::CONDITIONAL != 0 {
363	                OpaqueReason::ConditionalType
364	            } else if flags & flag::INDEXED_ACCESS != 0 {
365	                OpaqueReason::IndexedAccess { expression: text.clone() }
366	            } else {
367	                OpaqueReason::UnsupportedExpression
368	            };
369	            return Ok(degraded_type(text, reason));
370	        }
371	        if flags & flag::UNION != 0 {
372	            return self.union(info, cx).await;
373	        }
374	        if flags & flag::INTERSECTION != 0 {
375	            return self.intersection(info, cx).await;
376	        }
377	        if flags & flag::OBJECT != 0 {
378	            return self.object(info, cx).await;
379	        }
380	        Ok(named(self.display(info.id).await?, Vec::new()))
381	    }
382	
383	    /// How the checker prints the type; only ever a name for display, a truncated type's text, or the source of the two
384	    /// facts in [`crate::printed`].
385	    async fn display(&self, id: u64) -> Result<String, CallError> {
386	        self.printed(id, false).await
387	    }
388	
389	    /// How the checker prints the type with an alias at the top expanded and nothing cut short: the text a signature's
390	    /// parameter markers are read from, since the alias's name states no parameter list.
391	    async fn display_expanded(&self, id: u64) -> Result<String, CallError> {
392	        self.printed(id, true).await
393	    }
394	
395	    async fn printed(&self, id: u64, expanded: bool) -> Result<String, CallError> {
396	        let key = (id, expanded);
397	        if let Some(text) = self.state.printed.lock().ok().and_then(|printed| printed.get(&key).cloned()) {
398	            return Ok(text);
399	        }
400	        let text =
401	            if expanded { self.rpc.type_to_string_expanded(id).await? } else { self.rpc.type_to_string(id).await? };
402	        if let Ok(mut printed) = self.state.printed.lock() {
403	            printed.insert(key, text.clone());
404	        }
405	        Ok(text)
406	    }
407	
408	    /// The alias a type was written through, when it has one.
409	    async fn alias_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
410	        match &info.alias_symbol {
411	            Some(alias) => self.origin_of(alias, true, info.id).await,
412	            None => Ok(None),
413	        }
414	    }
415	
416	    /// What declares the type, when it has a name of its own: an alias, or an interface, class or instantiation of one.
417	    async fn origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
418	        if info.alias_symbol.is_some() {
419	            return self.alias_origin(info).await;
420	        }
421	        if info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0 {
422	            return self.symbol_origin(info).await;
423	        }
424	        Ok(None)
425	    }
426	
427	    /// The interface or class a type is, whatever alias it was written through.
428	    async fn symbol_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
429	        match &info.symbol {
430	            Some(symbol) => self.origin_of(symbol, false, info.id).await,
431	            None => Ok(None),
432	        }
433	    }
434	
435	    /// The declaration behind a symbol, asked once per symbol however many types refer to it.
436	    async fn origin_of(&self, symbol: &CompactSymbol, alias: bool, type_id: u64) -> Result<Option<Origin>, CallError> {
437	        let key = (alias, symbol.clone());
438	        if let Some(known) = self.state.origins.lock().ok().and_then(|origins| origins.get(&key).cloned()) {
439	            return Ok(known);
440	        }
441	        let found =
442	            if alias { self.rpc.alias_symbol(type_id).await? } else { self.rpc.symbol_of_type(type_id).await? };
443	        // `__type` and `__object` are the checker's names for a type that has none.
444	        let found = found.map(|symbol| Origin::of(&symbol, alias)).filter(|origin| !origin.name.starts_with("__"));
445	        if let Ok(mut origins) = self.state.origins.lock() {
446	            origins.insert(key, found.clone());
447	        }
448	        Ok(found)
449	    }
450	
451	    async fn type_parameter(&self, info: &TypeInfo) -> Result<PropType, CallError> {
452	        if info.is_this_type {
453	            return Ok(named("this".to_string(), Vec::new()));
454	        }
455	        let name = match self.rpc.symbol_of_type(info.id).await? {
456	            Some(symbol) => symbol.name,
457	            None => self.display(info.id).await?,
458	        };
459	        Ok(named(name, Vec::new()))
460	    }
461	
462	    async fn literal(&self, info: &TypeInfo) -> Result<PropType, CallError> {
463	        let flags = info.flags;
464	        let value = info.value.as_ref();
465	        let known = if flags & flag::BIG_INT_LITERAL != 0 {
466	            value.and_then(|value| value.as_str()).and_then(BigIntValue::parse).map(PropType::BigIntLiteral)
467	        } else if flags & flag::STRING_LITERAL != 0 {
468	            value.and_then(|value| value.as_str()).map(|text| PropType::StringLiteral(text.to_string()))
469	        } else {
470	            value.and_then(|value| value.as_f64()).map(PropType::NumberLiteral)
471	        };
472	        let Some(literal) = known else { return Ok(named(self.display(info.id).await?, Vec::new())) };
473	        if flags & flag::ENUM_LITERAL == 0 {
474	            return Ok(literal);
475	        }
476	        // A member of an enum is its value and keeps the enum's name.
477	        let Some(member) = self.rpc.symbol_of_type(info.id).await? else { return Ok(literal) };
478	        let Some(parent) = self.rpc.parent_of_symbol(&member.reference).await? else { return Ok(literal) };
479	        let value = match literal {
480	            PropType::StringLiteral(text) => EnumMemberValue::String(text),
481	            PropType::NumberLiteral(number) => EnumMemberValue::Number(number),
482	            other => return Ok(other),
483	        };
484	        Ok(PropType::EnumMember { enum_name: parent.name.into(), member: member.name.into(), value })
485	    }
486	
487	    /// The beta's responses carry neither `value` nor, in some builds, `intrinsicName` for `true` and `false`.
488	    async fn boolean_value(&self, info: &TypeInfo) -> Result<bool, CallError> {
489	        if let Some(name) = info.intrinsic_name.as_deref() {
490	            return Ok(name == "true");
491	        }
492	        if let Some(value) = info.value.as_ref().and_then(|value| value.as_bool()) {
493	            return Ok(value);
494	        }
495	        Ok(self.display(info.id).await? == "true")
496	    }
497	
498	    async fn template(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
499	        let origin = self.alias_origin(info).await?;
500	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
501	        let (holes, inner) = match gate {
502	            Gate::Stop(stopped) => return Ok(stopped),
503	            Gate::Open { parts, inner } => (parts, inner),
504	        };
505	        let mut types = self.convert_all(&holes, &inner).await?.into_iter();
506	        let mut parts = Vec::new();
507	        for text in &info.texts {
508	            if !text.is_empty() {
509	                parts.push(TemplatePart::Text(text.clone()));
510	            }
511	            if let Some(hole) = types.next() {
512	                parts.push(TemplatePart::Type(hole));
513	            }
514	        }
515	        Ok(PropType::TemplateLiteral(parts))
516	    }
517	
518	    /// The cut type for a cap: its declaration's name, else how the checker prints it.
519	    async fn truncated(
520	        &self,
521	        info: &TypeInfo,
522	        origin: Option<&Origin>,
523	        limit: TruncationLimit,
524	    ) -> Result<PropType, CallError> {
525	        let text = match origin {
526	            Some(origin) => origin.name.clone(),
527	            None => self.display(info.id).await?,
528	        };
529	        Ok(PropType::Truncated { text, limit })
530	    }
531	
532	    /// The reference back to a declaration that is being expanded around this type.
533	    async fn recursive(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<PropType, CallError> {
534	        let args = self.type_arguments_of(info, origin, cx).await?;
535	        Ok(PropType::Recursive { name: origin.name.clone().into(), args })
536	    }
537	
538	    /// The type arguments a name carries: an alias's own, or the instantiation's (without the `this` type the checker
539	    /// appends to a class or interface).
540	    async fn type_arguments_of(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<Vec<PropType>, CallError> {
541	        let arguments = if origin.alias {
542	            if info.alias_type_arguments.is_empty() {
543	                Vec::new()
544	            } else {
545	                self.rpc.alias_type_arguments(info.id).await?
546	            }
547	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
548	            let mut arguments = self.rpc.type_arguments(info.id).await?;
549	            while arguments.last().is_some_and(|argument| argument.is_this_type) {
550	                arguments.pop();
551	            }
552	            arguments
553	        } else {
554	            Vec::new()
555	        };
556	        self.convert_all(&arguments, &cx.argument()).await
557	    }
558	
559	    async fn named_type(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<PropType, CallError> {
560	        let args = self.type_arguments_of(info, origin, cx).await?;
561	        Ok(PropType::Named { name: origin.name.clone().into(), args })
562	    }
563	
564	    /// The one gate every descent into the parts of a type passes, before the parts are converted. It stops, in this
565	    /// order, a type that is an instantiation already being expanded around it (a back-reference to its declaration,
566	    /// whose arguments are the instantiation's), a type past [`MAX_DEPTH`], and a type whose `measure`d parts exceed the
567	    /// `limits`. `measure` fetches the parts and says how many there are; it is not called for a type stopped before.
568	    /// Otherwise the parts come back with the context to convert them in.
569	    async fn enter<T, F, Fut>(
570	        &self,
571	        info: &TypeInfo,
572	        origin: Option<&Origin>,
573	        cx: &Cx,
574	        limits: [usize; 2],
575	        measure: F,
576	    ) -> Result<Gate<T>, CallError>
577	    where
578	        T: Send,
579	        F: FnOnce() -> Fut + Send,
580	        Fut: Future<Output = Result<(T, usize), CallError>> + Send,
581	    {
582	        // The handle is the instantiation: `Box<string>` inside `Box<Box<string>>` is another type from the one around it.
583	        if let Some(origin) = origin
584	            && cx.encloses(info.id)
585	        {
586	            return Ok(Gate::Stop(self.recursive(info, origin, cx).await?));
587	        }
588	        if cx.depth >= MAX_DEPTH {
589	            return Ok(Gate::Stop(self.truncated(info, origin, TruncationLimit::Depth).await?));
590	        }
591	        let (parts, total) = measure().await?;
592	        if total > cx.limit(limits) {
593	            let limit = TruncationLimit::Members { total: to_u32(total) };
594	            return Ok(Gate::Stop(self.truncated(info, origin, limit).await?));
595	        }
596	        Ok(Gate::Open { parts, inner: cx.below(origin.map(|_| info.id)) })
597	    }
598	
599	    async fn union(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
600	        let origin = self.origin(info).await?;
601	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
602	            return Ok(terminal);
603	        }
604	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
605	        let (members, inner) = match gate {
606	            Gate::Stop(stopped) => return Ok(stopped),
607	            Gate::Open { parts, inner } => (parts, inner),
608	        };
609	        Ok(union_of(self.convert_all(&members, &inner).await?))
610	    }
611	
612	    /// The members of a union, intersection or template literal, and how many there are.
613	    async fn members_of(&self, info: &TypeInfo) -> Result<(Vec<TypeInfo>, usize), CallError> {
614	        let members = self.rpc.members(info.id).await?;
615	        let total = members.len();
616	        Ok((members, total))
617	    }
618	
619	    async fn intersection(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
620	        let origin = self.origin(info).await?;
621	        // A dependency's `Nested<Style>`-like alias is a name, as its interface would be.
622	        if let Some(origin) = &origin
623	            && origin.is_boundary()
624	        {
625	            return self.named_type(info, origin, cx).await;
626	        }
627	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
628	        let (members, inner) = match gate {
629	            Gate::Stop(stopped) => return Ok(stopped),
630	            Gate::Open { parts, inner } => (parts, inner),
631	        };
632	        let mut converted: Vec<PropType> = Vec::with_capacity(members.len());
633	        for member in self.convert_all(&members, &inner).await? {
634	            if !converted.contains(&member) {
635	                converted.push(member);
636	            }
637	        }
638	        Ok(if converted.len() == 1 { converted.swap_remove(0) } else { PropType::Intersection(converted) })
639	    }
640	
641	    async fn object(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
642	        if info.is_tuple_type {
643	            return self.tuple(info, cx).await;
644	        }
645	        if info.object_flags & flag::OBJECT_REFERENCE != 0
646	            && let Some(own) = self.symbol_origin(info).await?
647	            && own.in_lib()
648	            && !own.alias
649	            && matches!(own.name.as_str(), "Array" | "ReadonlyArray")
650	        {
651	            return self.array(info, own.name == "ReadonlyArray", cx).await;
652	        }
653	        let origin = self.origin(info).await?;
654	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
655	            return Ok(terminal);
656	        }
657	        let boundary = origin.as_ref().filter(|origin| origin.is_boundary());
658	        // A dependency's interface is a name unless it is callable; its properties are not asked for.
659	        if let Some(origin) = boundary
660	            && self.rpc.signatures(info.id, SignatureKind::Call).await?.is_empty()
661	        {
662	            return self.named_type(info, origin, cx).await;
663	        }
664	        let gate = self
665	            .enter(info, origin.as_ref(), cx, MAX_FIELDS, || async {
666	                let members = self.rpc.object_members(info.id).await?;
667	                // A dependency's function with properties of its own (a component, a hook) is a name, however many.
668	                let named = boundary.is_some() && !members.properties.is_empty();
669	                let total = if named { 0 } else { members.properties.len() + members.indexes.len() };
670	                Ok((members, total))
671	            })
672	            .await?;
673	        let (members, inner) = match gate {
674	            Gate::Stop(stopped) => return Ok(stopped),
675	            Gate::Open { parts, inner } => (parts, inner),
676	        };
677	        let ObjectMembers { calls, constructs, properties, indexes } = members;
678	        if let Some(origin) = boundary
679	            && !properties.is_empty()
680	        {
681	            return self.named_type(info, origin, cx).await;
682	        }
683	
684	        // Which of a signature's parameters are optional is read from the printed type here, and nowhere else.
685	        let Some(markers) = self.printed_markers(info.id, &calls, &constructs).await? else {
686	            return self.unreadable_signatures(info.id).await;
687	        };
688	        let mut signatures = Vec::with_capacity(calls.len() + constructs.len());
689	        for (kind, group, printed) in
690	            [(Kind::Call, &calls, &markers.calls), (Kind::Construct, &constructs, &markers.constructs)]
691	        {
692	            for (index, signature) in group.iter().enumerate() {
693	                let printed = printed.get(index).map(Vec::as_slice);
694	                let Some((type_params, params, return_type)) = self.signature_parts(signature, printed, &inner).await?
695	                else {
696	                    return self.unreadable_signatures(info.id).await;
697	                };
698	                signatures.push(CallSignature { kind, type_params, params, return_type });
699	            }
700	        }
701	        if signatures.len() == 1 && calls.len() == 1 && properties.is_empty() && indexes.is_empty() {
702	            let CallSignature { type_params, params, return_type, .. } = signatures.swap_remove(0);
703	            return Ok(PropType::Function { type_params, params, return_type: Box::new(return_type) });
704	        }
705	        let fields = self.fields(&properties, &indexes, &inner).await?;
706	        if signatures.is_empty() {
707	            return Ok(PropType::Object(fields));
708	        }
709	        Ok(PropType::Callable { signatures, fields })
710	    }
711	
712	    async fn array(&self, info: &TypeInfo, readonly: bool, cx: &Cx) -> Result<PropType, CallError> {
713	        // Only an alias can name an array that contains itself (`type Loop = Loop[]`); `Array` is the lib's.
714	        let origin = self.alias_origin(info).await?;
715	        let gate = self
716	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
717	                let arguments = self.rpc.type_arguments(info.id).await?;
718	                let total = arguments.len();
719	                Ok((arguments, total))
720	            })
721	            .await?;
722	        let (arguments, inner) = match gate {
723	            Gate::Stop(stopped) => return Ok(stopped),
724	            Gate::Open { parts, inner } => (parts, inner),
725	        };
726	        let Some(element) = arguments.first() else {
727	            return Ok(named(self.display(info.id).await?, Vec::new()));
728	        };
729	        let element = PropType::Array(Box::new(self.convert(element, &inner).await?));
730	        // `readonly T[]` is `ReadonlyArray<T>`: the same reference through another declaration.
731	        Ok(if readonly { PropType::Readonly(Box::new(element)) } else { element })
732	    }
733	
734	    async fn tuple(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
735	        let origin = self.alias_origin(info).await?;
736	        let gate = self
737	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
738	                // The reference carries the arguments; the tuple type it instantiates carries how each element is declared.
739	                let arguments = self.rpc.type_arguments(info.id).await?;
740	                let target = self.rpc.target_of_type(info.id).await?;
741	                let total = arguments.len();
742	                Ok(((arguments, target), total))
743	            })
744	            .await?;
745	        let ((arguments, target), inner) = match gate {
746	            Gate::Stop(stopped) => return Ok(stopped),
747	            Gate::Open { parts, inner } => (parts, inner),
748	        };
749	        let labels = if target.labeled_element_declarations.is_empty() {
750	            None
751	        } else {
752	            tuple_labels(&self.display(info.id).await?, arguments.len())
753	        };
754	        let element_types = self.convert_all(&arguments, &inner).await?;
755	        let mut elements = Vec::with_capacity(arguments.len());
756	        for (index, element_type) in element_types.into_iter().enumerate() {
757	            let element_flags = target.element_flags.get(index).copied().unwrap_or(1);
758	            let kind = if element_flags & flag::ELEMENT_VARIADIC != 0 {
759	                TupleElementKind::Variadic
760	            } else if element_flags & flag::ELEMENT_REST != 0 {
761	                TupleElementKind::Rest
762	            } else if element_flags & flag::ELEMENT_OPTIONAL != 0 {
763	                TupleElementKind::Optional
764	            } else {
765	                TupleElementKind::Required
766	            };
767	            let label = labels.as_ref().and_then(|labels| labels.get(index)).and_then(|label| TupleLabel::new(label));
768	            // An optional element's type argument includes the `undefined` of leaving it out.
769	            let element_type = without_undefined(element_type, kind == TupleElementKind::Optional);
770	            elements.push(TupleElement { element_type, kind, label });
771	        }
772	        let tuple = PropType::Tuple(elements);
773	        Ok(if target.readonly { PropType::Readonly(Box::new(tuple)) } else { tuple })
774	    }
775	
776	    async fn fields(
777	        &self,
778	        properties: &[SymbolInfo],
779	        indexes: &[crate::rpc::IndexInfo],
780	        cx: &Cx,
781	    ) -> Result<Vec<ObjectField>, CallError> {
782	        let references: Vec<_> = properties.iter().map(|property| &property.reference).collect();
783	        let (types, readonly) = if references.is_empty() {
784	            (Vec::new(), Vec::new())
785	        } else {
786	            (self.rpc.types_of_symbols(&references).await?, self.rpc.readonly_symbols(&references).await?)
787	        };
788	        let converted = self.convert_all(&types, cx).await?;
789	        let mut fields = Vec::with_capacity(properties.len() + indexes.len());
790	        for ((property, prop_type), readonly) in properties.iter().zip(converted).zip(readonly) {
791	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
792	            let prop_type = without_undefined(prop_type, !required);
793	            let mut field = ObjectField::new(property_name(&property.name), prop_type, required, String::new());
794	            field.readonly = readonly;
795	            fields.push(field);
796	        }
797	        let sides: Vec<TypeInfo> =
798	            indexes.iter().flat_map(|index| [index.key_type.clone(), index.value_type.clone()]).collect();
799	        let mut sides = self.convert_all(&sides, cx).await?.into_iter();
800	        for index in indexes {
801	            let (Some(key), Some(value)) = (sides.next(), sides.next()) else { break };
802	            let mut field = ObjectField::new("key", value, true, String::new());
803	            field.readonly = index.is_readonly;
804	            field.index_key = Some(Box::new(key));
805	            fields.push(field);
806	        }
807	        Ok(fields)
808	    }
809	
810	    /// The parameter markers of the signatures of an object type, as the checker prints the type (see
811	    /// [`crate::printed`]): the only source of which parameters are optional, since the API's parameter symbols do not
812	    /// say. `None` when some signature has a parameter and the printed type does not state one entry per signature.
813	    async fn printed_markers(
814	        &self,
815	        id: u64,
816	        calls: &[SignatureInfo],
817	        constructs: &[SignatureInfo],
818	    ) -> Result<Option<SignatureMarkers>, CallError> {
819	        if !calls.iter().chain(constructs).any(|signature| !signature.parameters.is_empty()) {
820	            let none = |count: usize| vec![Vec::new(); count];
821	            return Ok(Some(SignatureMarkers { calls: none(calls.len()), constructs: none(constructs.len()) }));
822	        }
823	        let stated = signature_markers(&self.display_expanded(id).await?);
824	        Ok(stated.filter(|stated| stated.calls.len() == calls.len() && stated.constructs.len() == constructs.len()))
825	    }
826	
827	    /// A type whose signatures state parameters that cannot be told optional from required is not given a shape that
828	    /// would assert one of them: it is opaque, with how the checker prints it.
829	    async fn unreadable_signatures(&self, id: u64) -> Result<PropType, CallError> {
830	        Ok(degraded_type(self.display_expanded(id).await?, OpaqueReason::UnsupportedExpression))
831	    }
832	
833	    /// One signature's type parameters, parameters and return type; `None` when a parameter that is not the rest
834	    /// parameter has no marker, since whether it is optional is then unknown and is not guessed.
835	    async fn signature_parts(
836	        &self,
837	        signature: &SignatureInfo,
838	        printed: Option<&[Marker]>,
839	        cx: &Cx,
840	    ) -> Result<Option<(Vec<String>, Vec<FunctionParam>, PropType)>, CallError> {
841	        let parameters = self.rpc.parameters(signature.id).await?;
842	        let has_rest = signature.flags & flag::SIGNATURE_HAS_REST_PARAMETER != 0;
843	        // A printed signature that does not give one entry per parameter states none of them.
844	        let markers = printed.filter(|markers| markers.len() == parameters.len());
845	        let known_without_markers = usize::from(has_rest);
846	        if markers.is_none() && parameters.len() > known_without_markers {
847	            return Ok(None);
848	        }
849	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
850	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
851	        let converted = self.convert_all(&types, cx).await?;
852	        let mut params = Vec::with_capacity(parameters.len());
853	        for (index, (parameter, param_type)) in parameters.iter().zip(converted).enumerate() {
854	            let marker = markers.and_then(|markers| markers.get(index)).copied().unwrap_or_default();
855	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
856	            let optional = marker.optional && !rest;
857	            let param_type = without_undefined(param_type, optional);
858	            // A destructured parameter has no name of its own; the checker calls it `__0`.
859	            let name = (!is_destructured(&parameter.name)).then(|| parameter.name.clone());
860	            params.push(FunctionParam { name, param_type, optional, rest });
861	        }
862	        let return_info = self.rpc.return_type(signature.id).await?;
863	        let return_type = self.convert(&return_info, cx).await?;
864	        let mut type_params = Vec::new();
865	        if !signature.type_parameters.is_empty() {
866	            for parameter in self.rpc.type_parameters(signature.id).await? {
867	                match self.rpc.symbol_of_type(parameter.id).await? {
868	                    Some(symbol) => type_params.push(symbol.name),
869	                    None => type_params.push(self.display(parameter.id).await?),
870	                }
871	            }
872	        }
873	        Ok(Some((type_params, params, return_type)))
874	    }
875	}
876	
877	/// The checker keys a property named by a symbol `__@<name>@<symbol id>`; the source writes `[Symbol.iterator]` or
878	/// `[brand]`. The id is the checker's and does not belong in an answer.
879	fn property_name(name: &str) -> String {
880	    const WELL_KNOWN: [&str; 15] = [
881	        "iterator",
882	        "asyncIterator",
883	        "hasInstance",
884	        "isConcatSpreadable",
885	        "match",
886	        "matchAll",
887	        "replace",
888	        "search",
889	        "species",
890	        "split",
891	        "toPrimitive",
892	        "toStringTag",
893	        "unscopables",
894	        "dispose",
895	        "asyncDispose",
896	    ];
897	    let Some((symbol, _id)) = name.strip_prefix("__@").and_then(|rest| rest.rsplit_once('@')) else {
898	        return name.to_string();
899	    };
900	    if WELL_KNOWN.contains(&symbol) { format!("[Symbol.{symbol}]") } else { format!("[{symbol}]") }
901	}
902	
903	fn is_destructured(name: &str) -> bool {
904	    name.strip_prefix("__").is_some_and(|rest| !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()))
905	}
906	
907	fn to_u32(count: usize) -> u32 {
908	    u32::try_from(count).unwrap_or(u32::MAX)
909	}
910	
911	fn named(name: String, args: Vec<PropType>) -> PropType {
912	    PropType::Named { name: name.into(), args }
913	}
914	
915	/// The types whose conversion needs nothing but their flags.
916	fn simple(info: &TypeInfo) -> Option<PropType> {
917	    let flags = info.flags;
918	    // `boolean` is the union `false | true` and carries both flags.
919	    if flags & flag::BOOLEAN != 0 {
920	        return Some(PropType::Boolean);
921	    }
922	    let known = [
923	        (flag::ANY, PropType::Any),
924	        (flag::UNKNOWN, PropType::Unknown),
925	        (flag::UNDEFINED, PropType::Undefined),
926	        (flag::NULL, PropType::Null),
927	        (flag::VOID, PropType::Void),
928	        (flag::NEVER, PropType::Never),
929	        (flag::STRING, PropType::String),
930	        (flag::NUMBER, PropType::Number),
931	        (flag::BIG_INT, named("bigint".to_string(), Vec::new())),
932	        (flag::ES_SYMBOL, named("symbol".to_string(), Vec::new())),
933	        (flag::NON_PRIMITIVE, named("object".to_string(), Vec::new())),
934	    ];
935	    known.into_iter().find(|(bit, _)| flags & bit != 0).map(|(_, converted)| converted)
936	}
937	
938	/// A union of converted members: `false | true` is `boolean`, a union inside a union is flattened, a repeated member
939	/// is kept once, and a union of one is that member.
940	fn union_of(converted: Vec<PropType>) -> PropType {
941	    let mut flat = Vec::with_capacity(converted.len());
942	    for member in converted {
943	        match member {
944	            PropType::Union(inner) => flat.extend(inner),
945	            other => flat.push(other),
946	        }
947	    }
948	    let both_booleans = flat.contains(&PropType::BoolLiteral(true)) && flat.contains(&PropType::BoolLiteral(false));
949	    let mut members: Vec<PropType> = Vec::with_capacity(flat.len());
950	    for member in flat {
951	        let member = match member {
952	            PropType::BoolLiteral(_) if both_booleans => PropType::Boolean,
953	            other => other,
954	        };
955	        if !members.contains(&member) {
956	            members.push(member);
957	        }
958	    }
959	    if members.len() == 1 { members.swap_remove(0) } else { PropType::Union(members) }
960	}
961	
962	/// An optional prop's type includes `undefined`; react-docgen-typescript drops it, as does the structural result.
963	pub(crate) fn without_undefined(prop_type: PropType, optional: bool) -> PropType {
964	    match prop_type {
965	        PropType::Union(members) if optional => {
966	            let mut kept: Vec<PropType> = members.into_iter().filter(|m| *m != PropType::Undefined).collect();
967	            if kept.len() == 1 { kept.swap_remove(0) } else { PropType::Union(kept) }
968	        }
969	        other => other,
970	    }
971	}
