1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which instantiations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. A handle is also what tells one instantiation from
9	//! another while a type is being expanded (`Box<Box<string>>` is two instantiations of one declaration): only its
10	//! equality is read, inside one conversion, so the answer does not depend on the numbers. The recursion marker that
11	//! results is named by the declaration (the alias or interface) and holds no handle. The memo is keyed by the enclosing
12	//! instantiations a conversion actually asked about, not by all of them (see [`State::memo`]).
13	//!
14	//! Every descent into the parts of a type (members, properties, elements, holes) passes [`Converter::enter`], which
15	//! decides before anything is fetched or converted whether the type is an enclosing instantiation (a back-reference),
16	//! sits too deep, or is too wide.
17	//!
18	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
19	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
20	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
21	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type. A dependency's
22	//! union of literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
23	//! [`PropType::Truncated`], never the checker's text standing in as a name.
24	
25	use std::future::Future;
26	use std::pin::Pin;
27	use std::sync::atomic::{AtomicU64, Ordering};
28	use std::sync::{Arc, Mutex};
29	
30	use caliper_docgen_core::types::semantic::{degraded_type, unresolved_type};
31	use caliper_docgen_core::types::{
32	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
33	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
34	};
35	use rustc_hash::FxHashMap;
36	
37	use crate::printed::{Marker, SignatureMarkers, signature_markers, tuple_labels};
38	use crate::rpc::{
39	    CallError, CompactSymbol, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, TypeInfo, flag,
40	};
41	
42	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
43	const MAX_DEPTH: u8 = 5;
44	/// The most properties an object type lists at the top (a prop's own type) and below it.
45	const MAX_FIELDS: [usize; 2] = [100, 40];
46	/// The most members a union or intersection lists at the top and below it.
47	const MAX_MEMBERS: [usize; 2] = [500, 120];
48	
49	/// What a descent found at [`Converter::enter`].
50	enum Gate<T> {
51	    /// The type is not expanded: it is a back-reference, or a cap cut it.
52	    Stop(PropType),
53	    /// The parts of the type, and the context to convert them in.
54	    Open { parts: T, inner: Cx },
55	}
56	
57	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
58	
59	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
60	/// checker's type handle) enclose it, outermost first.
61	#[derive(Debug, Clone, Default)]
62	pub(crate) struct Cx {
63	    depth: u8,
64	    enclosing: Arc<Vec<u64>>,
65	    /// The conversion this context belongs to, which records which enclosing instantiations it asks about. `None` at
66	    /// the roots.
67	    frame: Option<Arc<Frame>>,
68	}
69	
70	/// What one conversion has asked of the instantiations enclosing it, kept to build its memo entry (see
71	/// [`State::memo`]).
72	#[derive(Debug)]
73	struct Frame {
74	    /// How many instantiations enclosed the type when its conversion began: those below this are the outer context, the
75	    /// rest were opened by the conversion itself.
76	    base: usize,
77	    asked: Mutex<Asked>,
78	}
79	
80	#[derive(Debug, Default)]
81	struct Asked {
82	    /// The handles this conversion's own gate compared against its enclosing instantiations.
83	    ids: Vec<u64>,
84	    /// The sets asked by the conversions of its parts, each with the instantiations this conversion had opened by then:
85	    /// those were answered inside it and do not depend on its outer context.
86	    parts: Vec<(Arc<[u64]>, Vec<u64>)>,
87	}
88	
89	impl Frame {
90	    fn new(base: usize) -> Self {
91	        Frame { base, asked: Mutex::default() }
92	    }
93	
94	    fn lock(&self) -> std::sync::MutexGuard<'_, Asked> {
95	        self.asked.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
96	    }
97	
98	    fn ask(&self, id: u64) {
99	        self.lock().ids.push(id);
100	    }
101	
102	    /// A part of this conversion was converted (or recalled) under `enclosing`, having asked about `asked`.
103	    fn absorb(&self, asked: &Arc<[u64]>, enclosing: &[u64]) {
104	        if !asked.is_empty() {
105	            self.lock().parts.push((asked.clone(), enclosing.get(self.base..).unwrap_or_default().to_vec()));
106	        }
107	    }
108	
109	    /// Every handle the conversion asked about whose answer came from outside it: sorted, once each.
110	    fn finish(&self) -> Arc<[u64]> {
111	        let asked = self.lock();
112	        let mut ids = asked.ids.clone();
113	        for (part, opened) in &asked.parts {
114	            ids.extend(part.iter().copied().filter(|id| !opened.contains(id)));
115	        }
116	        ids.sort_unstable();
117	        ids.dedup();
118	        ids.into()
119	    }
120	}
121	
122	impl Cx {
123	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
124	    /// and passes [`Converter::enter`] if it has parts.
125	    fn argument(&self) -> Cx {
126	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone(), frame: self.frame.clone() }
127	    }
128	
129	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
130	    /// only a name can be pointed back to.
131	    fn below(&self, instance: Option<u64>) -> Cx {
132	        let mut enclosing = self.enclosing.clone();
133	        if let Some(id) = instance
134	            && !enclosing.contains(&id)
135	        {
136	            let mut grown = (*enclosing).clone();
137	            grown.push(id);
138	            enclosing = Arc::new(grown);
139	        }
140	        Cx { depth: self.depth.saturating_add(1), enclosing, frame: self.frame.clone() }
141	    }
142	
143	    /// Whether `id` is an instantiation being expanded around the type. The conversion in progress is recorded to have
144	    /// asked, whichever the answer.
145	    fn encloses(&self, id: u64) -> bool {
146	        if let Some(frame) = &self.frame {
147	            frame.ask(id);
148	        }
149	        self.enclosing.contains(&id)
150	    }
151	
152	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
153	        limits[usize::from(self.depth > 0).min(N - 1)]
154	    }
155	}
