215	/// A converted type, with the enclosing instantiations its conversion depended on.
216	#[derive(Debug)]
217	struct Entry {
218	    /// Every handle the conversion compared against the instantiations enclosing it, sorted.
219	    asked: Arc<[u64]>,
220	    /// Those of `asked` that did enclose it.
221	    enclosed_by: Vec<u64>,
222	    converted: PropType,
223	}
224	
225	impl Entry {
226	    /// Whether the conversion would go the same way inside `enclosing`: among the handles it asked about, the ones
227	    /// that enclose the type there are exactly `enclosed_by`.
228	    fn holds_in(&self, enclosing: &[u64]) -> bool {
229	        self.enclosed_by.iter().all(|id| enclosing.contains(id))
230	            && enclosing.iter().all(|id| self.enclosed_by.contains(id) || self.asked.binary_search(id).is_err())
231	    }
232	}
233	
234	type Memo = Mutex<FxHashMap<(u64, u8), Vec<Arc<Entry>>>>;
235	
236	#[derive(Default)]
237	struct State {
238	    /// Conversions by (type handle, depth), each entry with the enclosing instantiations it depended on. The handles
239	    /// are valid inside this snapshot only.
240	    ///
241	    /// Why an entry may be reused where [`Entry::holds_in`] says. A conversion reads its context in two ways only: the
242	    /// depth, which is in the key, and [`Cx::encloses`], the question whether a handle is an instantiation being
243	    /// expanded around the type. Everything else it reads is the checker's answer about the type, which does not change
244	    /// inside a snapshot. So a conversion is a deterministic walk whose every step is fixed by the type, the depth and
245	    /// the answers to those questions, in the order they are asked. Run it again where each handle it asked about has
246	    /// the same answer, and it asks the same questions in the same order and returns the same type. A handle that the
247	    /// conversion opened itself is settled inside it (it was found not to enclose the type at its own gate, which is
248	    /// recorded), so only the handles asked of the outer context are kept. A type in no cycle with its context asks
249	    /// nothing that encloses it and holds everywhere; one in a cycle holds where the same part of the cycle encloses
250	    /// it. Entries that hold in a context all agree, so which of them is found first, and so the order in which
251	    /// types were first reached, cannot show in the output.
252	    memo: Memo,
253	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
254	    /// By (type handle, whether printed expanded: see [`Rpc::type_to_string_expanded`]).
255	    printed: Mutex<FxHashMap<(u64, bool), String>>,
256	    hits: AtomicU64,
257	    misses: AtomicU64,
258	}
