260	#[derive(Clone)]
261	pub(crate) struct Converter {
262	    rpc: Arc<Rpc>,
263	    state: Arc<State>,
264	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
265	    reverse: bool,
266	}
267	
268	impl Converter {
269	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
270	        Self { rpc, state: Arc::new(State::default()), reverse }
271	    }
272	
273	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
274	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
275	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
276	        let order: Box<dyn Iterator<Item = usize> + Send> =
277	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
278	        for index in order {
279	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
280	                *slot = Some(self.convert(info, cx).await?);
281	            }
282	        }
283	        Ok(slots.into_iter().flatten().collect())
284	    }
285	
286	    /// Memo hits and misses so far, for the debug line.
287	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
288	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
289	    }
290	
291	    /// The own types of a component's props, from the top.
292	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
293	        self.convert_all(infos, &Cx::default()).await
294	    }
295	
296	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
297	        Box::pin(async move {
298	            if let Some(entry) = self.recall(info.id, cx) {
299	                self.state.hits.fetch_add(1, Ordering::Relaxed);
300	                if let Some(frame) = &cx.frame {
301	                    frame.absorb(&entry.asked, &cx.enclosing);
302	                }
303	                return Ok(entry.converted.clone());
304	            }
305	            self.state.misses.fetch_add(1, Ordering::Relaxed);
306	            let frame = Arc::new(Frame::new(cx.enclosing.len()));
307	            let own = Cx { depth: cx.depth, enclosing: cx.enclosing.clone(), frame: Some(frame.clone()) };
308	            let converted = self.uncached(info, &own).await?;
309	            let asked = frame.finish();
310	            if let Some(parent) = &cx.frame {
311	                parent.absorb(&asked, &cx.enclosing);
312	            }
313	            let enclosed_by = cx.enclosing.iter().copied().filter(|id| asked.binary_search(id).is_ok()).collect();
314	            let entry = Arc::new(Entry { asked, enclosed_by, converted: converted.clone() });
315	            if let Ok(mut memo) = self.state.memo.lock() {
316	                memo.entry((info.id, cx.depth)).or_default().push(entry);
317	            }
318	            Ok(converted)
319	        })
320	    }
321	
322	    /// The entry for the type at this depth that holds inside the instantiations enclosing it, if there is one.
323	    fn recall(&self, id: u64, cx: &Cx) -> Option<Arc<Entry>> {
324	        let memo = self.state.memo.lock().ok()?;
325	        memo.get(&(id, cx.depth))?.iter().find(|entry| entry.holds_in(&cx.enclosing)).cloned()
326	    }
327	
328	    async fn uncached(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
329	        if info.is_error() {
330	            return Ok(unresolved_type(self.display(info.id).await?));
331	        }
332	        if let Some(simple) = simple(info) {
333	            return Ok(simple);
334	        }
335	        let flags = info.flags;
336	        if flags & flag::TYPE_PARAMETER != 0 {
337	            return self.type_parameter(info).await;
338	        }
339	        if flags & (flag::STRING_LITERAL | flag::NUMBER_LITERAL | flag::BIG_INT_LITERAL) != 0 {
340	            return self.literal(info).await;
341	        }
342	        if flags & flag::BOOLEAN_LITERAL != 0 {
343	            return Ok(PropType::BoolLiteral(self.boolean_value(info).await?));
344	        }
345	        if flags & flag::UNIQUE_ES_SYMBOL != 0 {
346	            let name = self.rpc.symbol_of_type(info.id).await?.map(|symbol| symbol.name);
347	            return Ok(match name {
348	                Some(name) => PropType::UniqueSymbol { name: name.into() },
349	                None => named(self.display(info.id).await?, Vec::new()),
350	            });
351	        }
352	        if flags & flag::TEMPLATE_LITERAL != 0 {
353	            return self.template(info, cx).await;
354	        }
355	        // `Uppercase<string>` and its siblings: a name, since there is no shape to expand.
356	        if flags & flag::STRING_MAPPING != 0 {
357	            return Ok(named(self.display(info.id).await?, Vec::new()));
358	        }
359	        // Types the checker could not resolve because a type parameter is still open.
360	        if flags & (flag::CONDITIONAL | flag::INDEXED_ACCESS | flag::INDEX | flag::SUBSTITUTION) != 0 {
361	            let text = self.display(info.id).await?;
362	            let reason = if flags & flag::CONDITIONAL != 0 {
363	                OpaqueReason::ConditionalType
364	            } else if flags & flag::INDEXED_ACCESS != 0 {
365	                OpaqueReason::IndexedAccess { expression: text.clone() }
366	            } else {
367	                OpaqueReason::UnsupportedExpression
368	            };
369	            return Ok(degraded_type(text, reason));
370	        }
371	        if flags & flag::UNION != 0 {
372	            return self.union(info, cx).await;
373	        }
374	        if flags & flag::INTERSECTION != 0 {
375	            return self.intersection(info, cx).await;
376	        }
377	        if flags & flag::OBJECT != 0 {
378	            return self.object(info, cx).await;
379	        }
380	        Ok(named(self.display(info.id).await?, Vec::new()))
381	    }
