383	    /// How the checker prints the type; only ever a name for display, a truncated type's text, or the source of the two
384	    /// facts in [`crate::printed`].
385	    async fn display(&self, id: u64) -> Result<String, CallError> {
386	        self.printed(id, false).await
387	    }
