395	    async fn printed(&self, id: u64, expanded: bool) -> Result<String, CallError> {
396	        let key = (id, expanded);
397	        if let Some(text) = self.state.printed.lock().ok().and_then(|printed| printed.get(&key).cloned()) {
398	            return Ok(text);
399	        }
400	        let text =
401	            if expanded { self.rpc.type_to_string_expanded(id).await? } else { self.rpc.type_to_string(id).await? };
402	        if let Ok(mut printed) = self.state.printed.lock() {
403	            printed.insert(key, text.clone());
404	        }
405	        Ok(text)
406	    }
