408	    /// The alias a type was written through, when it has one.
409	    async fn alias_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
410	        match &info.alias_symbol {
411	            Some(alias) => self.origin_of(alias, true, info.id).await,
412	            None => Ok(None),
