416	    /// What declares the type, when it has a name of its own: an alias, or an interface, class or instantiation of one.
417	    async fn origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
418	        if info.alias_symbol.is_some() {
419	            return self.alias_origin(info).await;
420	        }
421	        if info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0 {
422	            return self.symbol_origin(info).await;
423	        }
424	        Ok(None)
425	    }
