427	    /// The interface or class a type is, whatever alias it was written through.
428	    async fn symbol_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
429	        match &info.symbol {
430	            Some(symbol) => self.origin_of(symbol, false, info.id).await,
431	            None => Ok(None),
432	        }
