435	    /// The declaration behind a symbol, asked once per symbol however many types refer to it.
436	    async fn origin_of(&self, symbol: &CompactSymbol, alias: bool, type_id: u64) -> Result<Option<Origin>, CallError> {
437	        let key = (alias, symbol.clone());
438	        if let Some(known) = self.state.origins.lock().ok().and_then(|origins| origins.get(&key).cloned()) {
439	            return Ok(known);
440	        }
441	        let found =
442	            if alias { self.rpc.alias_symbol(type_id).await? } else { self.rpc.symbol_of_type(type_id).await? };
443	        // `__type` and `__object` are the checker's names for a type that has none.
444	        let found = found.map(|symbol| Origin::of(&symbol, alias)).filter(|origin| !origin.name.starts_with("__"));
445	        if let Ok(mut origins) = self.state.origins.lock() {
446	            origins.insert(key, found.clone());
447	        }
448	        Ok(found)
449	    }
