451	    async fn type_parameter(&self, info: &TypeInfo) -> Result<PropType, CallError> {
452	        if info.is_this_type {
453	            return Ok(named("this".to_string(), Vec::new()));
454	        }
455	        let name = match self.rpc.symbol_of_type(info.id).await? {
456	            Some(symbol) => symbol.name,
457	            None => self.display(info.id).await?,
458	        };
459	        Ok(named(name, Vec::new()))
460	    }
