462	    async fn literal(&self, info: &TypeInfo) -> Result<PropType, CallError> {
463	        let flags = info.flags;
464	        let value = info.value.as_ref();
465	        let known = if flags & flag::BIG_INT_LITERAL != 0 {
466	            value.and_then(|value| value.as_str()).and_then(BigIntValue::parse).map(PropType::BigIntLiteral)
467	        } else if flags & flag::STRING_LITERAL != 0 {
468	            value.and_then(|value| value.as_str()).map(|text| PropType::StringLiteral(text.to_string()))
469	        } else {
470	            value.and_then(|value| value.as_f64()).map(PropType::NumberLiteral)
471	        };
472	        let Some(literal) = known else { return Ok(named(self.display(info.id).await?, Vec::new())) };
473	        if flags & flag::ENUM_LITERAL == 0 {
474	            return Ok(literal);
475	        }
476	        // A member of an enum is its value and keeps the enum's name.
477	        let Some(member) = self.rpc.symbol_of_type(info.id).await? else { return Ok(literal) };
478	        let Some(parent) = self.rpc.parent_of_symbol(&member.reference).await? else { return Ok(literal) };
479	        let value = match literal {
480	            PropType::StringLiteral(text) => EnumMemberValue::String(text),
481	            PropType::NumberLiteral(number) => EnumMemberValue::Number(number),
482	            other => return Ok(other),
483	        };
484	        Ok(PropType::EnumMember { enum_name: parent.name.into(), member: member.name.into(), value })
485	    }
