487	    /// The beta's responses carry neither `value` nor, in some builds, `intrinsicName` for `true` and `false`.
488	    async fn boolean_value(&self, info: &TypeInfo) -> Result<bool, CallError> {
489	        if let Some(name) = info.intrinsic_name.as_deref() {
490	            return Ok(name == "true");
491	        }
492	        if let Some(value) = info.value.as_ref().and_then(|value| value.as_bool()) {
493	            return Ok(value);
494	        }
495	        Ok(self.display(info.id).await? == "true")
496	    }
