498	    async fn template(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
499	        let origin = self.alias_origin(info).await?;
500	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
501	        let (holes, inner) = match gate {
502	            Gate::Stop(stopped) => return Ok(stopped),
503	            Gate::Open { parts, inner } => (parts, inner),
504	        };
505	        let mut types = self.convert_all(&holes, &inner).await?.into_iter();
506	        let mut parts = Vec::new();
507	        for text in &info.texts {
508	            if !text.is_empty() {
509	                parts.push(TemplatePart::Text(text.clone()));
510	            }
511	            if let Some(hole) = types.next() {
512	                parts.push(TemplatePart::Type(hole));
513	            }
514	        }
515	        Ok(PropType::TemplateLiteral(parts))
516	    }
