538	    /// The type arguments a name carries: an alias's own, or the instantiation's (without the `this` type the checker
539	    /// appends to a class or interface).
540	    async fn type_arguments_of(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<Vec<PropType>, CallError> {
541	        let arguments = if origin.alias {
542	            if info.alias_type_arguments.is_empty() {
543	                Vec::new()
544	            } else {
545	                self.rpc.alias_type_arguments(info.id).await?
546	            }
547	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
548	            let mut arguments = self.rpc.type_arguments(info.id).await?;
549	            while arguments.last().is_some_and(|argument| argument.is_this_type) {
550	                arguments.pop();
551	            }
552	            arguments
553	        } else {
