564	    /// The one gate every descent into the parts of a type passes, before the parts are converted. It stops, in this
565	    /// order, a type that is an instantiation already being expanded around it (a back-reference to its declaration,
566	    /// whose arguments are the instantiation's), a type past [`MAX_DEPTH`], and a type whose `measure`d parts exceed the
567	    /// `limits`. `measure` fetches the parts and says how many there are; it is not called for a type stopped before.
568	    /// Otherwise the parts come back with the context to convert them in.
569	    async fn enter<T, F, Fut>(
570	        &self,
571	        info: &TypeInfo,
572	        origin: Option<&Origin>,
573	        cx: &Cx,
574	        limits: [usize; 2],
575	        measure: F,
576	    ) -> Result<Gate<T>, CallError>
577	    where
578	        T: Send,
579	        F: FnOnce() -> Fut + Send,
580	        Fut: Future<Output = Result<(T, usize), CallError>> + Send,
581	    {
582	        // The handle is the instantiation: `Box<string>` inside `Box<Box<string>>` is another type from the one around it.
583	        if let Some(origin) = origin
584	            && cx.encloses(info.id)
585	        {
586	            return Ok(Gate::Stop(self.recursive(info, origin, cx).await?));
587	        }
588	        if cx.depth >= MAX_DEPTH {
589	            return Ok(Gate::Stop(self.truncated(info, origin, TruncationLimit::Depth).await?));
590	        }
591	        let (parts, total) = measure().await?;
592	        if total > cx.limit(limits) {
593	            let limit = TruncationLimit::Members { total: to_u32(total) };
594	            return Ok(Gate::Stop(self.truncated(info, origin, limit).await?));
595	        }
596	        Ok(Gate::Open { parts, inner: cx.below(origin.map(|_| info.id)) })
597	    }
598	
599	    async fn union(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
600	        let origin = self.origin(info).await?;
601	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
602	            return Ok(terminal);
603	        }
604	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
605	        let (members, inner) = match gate {
606	            Gate::Stop(stopped) => return Ok(stopped),
607	            Gate::Open { parts, inner } => (parts, inner),
608	        };
609	        Ok(union_of(self.convert_all(&members, &inner).await?))
610	    }
