612	    /// The members of a union, intersection or template literal, and how many there are.
613	    async fn members_of(&self, info: &TypeInfo) -> Result<(Vec<TypeInfo>, usize), CallError> {
614	        let members = self.rpc.members(info.id).await?;
615	        let total = members.len();
616	        Ok((members, total))
617	    }
618	
619	    async fn intersection(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
620	        let origin = self.origin(info).await?;
621	        // A dependency's `Nested<Style>`-like alias is a name, as its interface would be.
622	        if let Some(origin) = &origin
623	            && origin.is_boundary()
624	        {
625	            return self.named_type(info, origin, cx).await;
626	        }
627	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
628	        let (members, inner) = match gate {
629	            Gate::Stop(stopped) => return Ok(stopped),
630	            Gate::Open { parts, inner } => (parts, inner),
631	        };
632	        let mut converted: Vec<PropType> = Vec::with_capacity(members.len());
633	        for member in self.convert_all(&members, &inner).await? {
634	            if !converted.contains(&member) {
635	                converted.push(member);
636	            }
637	        }
638	        Ok(if converted.len() == 1 { converted.swap_remove(0) } else { PropType::Intersection(converted) })
639	    }
640	
641	    async fn object(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
642	        if info.is_tuple_type {
643	            return self.tuple(info, cx).await;
644	        }
645	        if info.object_flags & flag::OBJECT_REFERENCE != 0
646	            && let Some(own) = self.symbol_origin(info).await?
647	            && own.in_lib()
648	            && !own.alias
649	            && matches!(own.name.as_str(), "Array" | "ReadonlyArray")
650	        {
651	            return self.array(info, own.name == "ReadonlyArray", cx).await;
652	        }
653	        let origin = self.origin(info).await?;
654	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
655	            return Ok(terminal);
656	        }
657	        let boundary = origin.as_ref().filter(|origin| origin.is_boundary());
658	        // A dependency's interface is a name unless it is callable; its properties are not asked for.
659	        if let Some(origin) = boundary
660	            && self.rpc.signatures(info.id, SignatureKind::Call).await?.is_empty()
661	        {
662	            return self.named_type(info, origin, cx).await;
663	        }
664	        let gate = self
665	            .enter(info, origin.as_ref(), cx, MAX_FIELDS, || async {
666	                let members = self.rpc.object_members(info.id).await?;
667	                // A dependency's function with properties of its own (a component, a hook) is a name, however many.
668	                let named = boundary.is_some() && !members.properties.is_empty();
669	                let total = if named { 0 } else { members.properties.len() + members.indexes.len() };
670	                Ok((members, total))
671	            })
672	            .await?;
673	        let (members, inner) = match gate {
674	            Gate::Stop(stopped) => return Ok(stopped),
675	            Gate::Open { parts, inner } => (parts, inner),
676	        };
677	        let ObjectMembers { calls, constructs, properties, indexes } = members;
678	        if let Some(origin) = boundary
679	            && !properties.is_empty()
680	        {
681	            return self.named_type(info, origin, cx).await;
682	        }
683	
684	        // Which of a signature's parameters are optional is read from the printed type here, and nowhere else.
685	        let Some(markers) = self.printed_markers(info.id, &calls, &constructs).await? else {
686	            return self.unreadable_signatures(info.id).await;
687	        };
688	        let mut signatures = Vec::with_capacity(calls.len() + constructs.len());
689	        for (kind, group, printed) in
690	            [(Kind::Call, &calls, &markers.calls), (Kind::Construct, &constructs, &markers.constructs)]
691	        {
692	            for (index, signature) in group.iter().enumerate() {
693	                let printed = printed.get(index).map(Vec::as_slice);
694	                let Some((type_params, params, return_type)) = self.signature_parts(signature, printed, &inner).await?
695	                else {
696	                    return self.unreadable_signatures(info.id).await;
697	                };
698	                signatures.push(CallSignature { kind, type_params, params, return_type });
699	            }
700	        }
701	        if signatures.len() == 1 && calls.len() == 1 && properties.is_empty() && indexes.is_empty() {
702	            let CallSignature { type_params, params, return_type, .. } = signatures.swap_remove(0);
703	            return Ok(PropType::Function { type_params, params, return_type: Box::new(return_type) });
704	        }
705	        let fields = self.fields(&properties, &indexes, &inner).await?;
706	        if signatures.is_empty() {
707	            return Ok(PropType::Object(fields));
708	        }
709	        Ok(PropType::Callable { signatures, fields })
710	    }
711	
712	    async fn array(&self, info: &TypeInfo, readonly: bool, cx: &Cx) -> Result<PropType, CallError> {
713	        // Only an alias can name an array that contains itself (`type Loop = Loop[]`); `Array` is the lib's.
714	        let origin = self.alias_origin(info).await?;
715	        let gate = self
716	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
717	                let arguments = self.rpc.type_arguments(info.id).await?;
718	                let total = arguments.len();
719	                Ok((arguments, total))
720	            })
721	            .await?;
722	        let (arguments, inner) = match gate {
723	            Gate::Stop(stopped) => return Ok(stopped),
724	            Gate::Open { parts, inner } => (parts, inner),
725	        };
726	        let Some(element) = arguments.first() else {
727	            return Ok(named(self.display(info.id).await?, Vec::new()));
728	        };
729	        let element = PropType::Array(Box::new(self.convert(element, &inner).await?));
730	        // `readonly T[]` is `ReadonlyArray<T>`: the same reference through another declaration.
731	        Ok(if readonly { PropType::Readonly(Box::new(element)) } else { element })
732	    }
733	
734	    async fn tuple(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
735	        let origin = self.alias_origin(info).await?;
736	        let gate = self
737	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
738	                // The reference carries the arguments; the tuple type it instantiates carries how each element is declared.
739	                let arguments = self.rpc.type_arguments(info.id).await?;
740	                let target = self.rpc.target_of_type(info.id).await?;
741	                let total = arguments.len();
742	                Ok(((arguments, target), total))
743	            })
744	            .await?;
745	        let ((arguments, target), inner) = match gate {
746	            Gate::Stop(stopped) => return Ok(stopped),
747	            Gate::Open { parts, inner } => (parts, inner),
748	        };
749	        let labels = if target.labeled_element_declarations.is_empty() {
750	            None
751	        } else {
752	            tuple_labels(&self.display(info.id).await?, arguments.len())
753	        };
754	        let element_types = self.convert_all(&arguments, &inner).await?;
755	        let mut elements = Vec::with_capacity(arguments.len());
756	        for (index, element_type) in element_types.into_iter().enumerate() {
757	            let element_flags = target.element_flags.get(index).copied().unwrap_or(1);
758	            let kind = if element_flags & flag::ELEMENT_VARIADIC != 0 {
759	                TupleElementKind::Variadic
760	            } else if element_flags & flag::ELEMENT_REST != 0 {
761	                TupleElementKind::Rest
762	            } else if element_flags & flag::ELEMENT_OPTIONAL != 0 {
763	                TupleElementKind::Optional
764	            } else {
765	                TupleElementKind::Required
766	            };
767	            let label = labels.as_ref().and_then(|labels| labels.get(index)).and_then(|label| TupleLabel::new(label));
768	            // An optional element's type argument includes the `undefined` of leaving it out.
769	            let element_type = without_undefined(element_type, kind == TupleElementKind::Optional);
770	            elements.push(TupleElement { element_type, kind, label });
771	        }
772	        let tuple = PropType::Tuple(elements);
773	        Ok(if target.readonly { PropType::Readonly(Box::new(tuple)) } else { tuple })
774	    }
775	
776	    async fn fields(
777	        &self,
778	        properties: &[SymbolInfo],
779	        indexes: &[crate::rpc::IndexInfo],
780	        cx: &Cx,
781	    ) -> Result<Vec<ObjectField>, CallError> {
782	        let references: Vec<_> = properties.iter().map(|property| &property.reference).collect();
783	        let (types, readonly) = if references.is_empty() {
784	            (Vec::new(), Vec::new())
785	        } else {
786	            (self.rpc.types_of_symbols(&references).await?, self.rpc.readonly_symbols(&references).await?)
787	        };
788	        let converted = self.convert_all(&types, cx).await?;
789	        let mut fields = Vec::with_capacity(properties.len() + indexes.len());
790	        for ((property, prop_type), readonly) in properties.iter().zip(converted).zip(readonly) {
791	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
792	            let prop_type = without_undefined(prop_type, !required);
793	            let mut field = ObjectField::new(property_name(&property.name), prop_type, required, String::new());
794	            field.readonly = readonly;
795	            fields.push(field);
796	        }
797	        let sides: Vec<TypeInfo> =
798	            indexes.iter().flat_map(|index| [index.key_type.clone(), index.value_type.clone()]).collect();
799	        let mut sides = self.convert_all(&sides, cx).await?.into_iter();
800	        for index in indexes {
801	            let (Some(key), Some(value)) = (sides.next(), sides.next()) else { break };
802	            let mut field = ObjectField::new("key", value, true, String::new());
803	            field.readonly = index.is_readonly;
804	            field.index_key = Some(Box::new(key));
805	            fields.push(field);
806	        }
807	        Ok(fields)
808	    }
809	
810	    /// The parameter markers of the signatures of an object type, as the checker prints the type (see
811	    /// [`crate::printed`]): the only source of which parameters are optional, since the API's parameter symbols do not
812	    /// say. `None` when some signature has a parameter and the printed type does not state one entry per signature.
813	    async fn printed_markers(
814	        &self,
815	        id: u64,
816	        calls: &[SignatureInfo],
817	        constructs: &[SignatureInfo],
818	    ) -> Result<Option<SignatureMarkers>, CallError> {
819	        if !calls.iter().chain(constructs).any(|signature| !signature.parameters.is_empty()) {
820	            let none = |count: usize| vec![Vec::new(); count];
821	            return Ok(Some(SignatureMarkers { calls: none(calls.len()), constructs: none(constructs.len()) }));
822	        }
823	        let stated = signature_markers(&self.display_expanded(id).await?);
824	        Ok(stated.filter(|stated| stated.calls.len() == calls.len() && stated.constructs.len() == constructs.len()))
825	    }
826	
827	    /// A type whose signatures state parameters that cannot be told optional from required is not given a shape that
828	    /// would assert one of them: it is opaque, with how the checker prints it.
829	    async fn unreadable_signatures(&self, id: u64) -> Result<PropType, CallError> {
830	        Ok(degraded_type(self.display_expanded(id).await?, OpaqueReason::UnsupportedExpression))
831	    }
832	
833	    /// One signature's type parameters, parameters and return type; `None` when a parameter that is not the rest
834	    /// parameter has no marker, since whether it is optional is then unknown and is not guessed.
835	    async fn signature_parts(
836	        &self,
837	        signature: &SignatureInfo,
838	        printed: Option<&[Marker]>,
839	        cx: &Cx,
840	    ) -> Result<Option<(Vec<String>, Vec<FunctionParam>, PropType)>, CallError> {
841	        let parameters = self.rpc.parameters(signature.id).await?;
842	        let has_rest = signature.flags & flag::SIGNATURE_HAS_REST_PARAMETER != 0;
843	        // A printed signature that does not give one entry per parameter states none of them.
844	        let markers = printed.filter(|markers| markers.len() == parameters.len());
845	        let known_without_markers = usize::from(has_rest);
846	        if markers.is_none() && parameters.len() > known_without_markers {
847	            return Ok(None);
848	        }
849	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
850	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
851	        let converted = self.convert_all(&types, cx).await?;
852	        let mut params = Vec::with_capacity(parameters.len());
853	        for (index, (parameter, param_type)) in parameters.iter().zip(converted).enumerate() {
854	            let marker = markers.and_then(|markers| markers.get(index)).copied().unwrap_or_default();
855	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
856	            let optional = marker.optional && !rest;
857	            let param_type = without_undefined(param_type, optional);
858	            // A destructured parameter has no name of its own; the checker calls it `__0`.
859	            let name = (!is_destructured(&parameter.name)).then(|| parameter.name.clone());
860	            params.push(FunctionParam { name, param_type, optional, rest });
861	        }
862	        let return_info = self.rpc.return_type(signature.id).await?;
863	        let return_type = self.convert(&return_info, cx).await?;
864	        let mut type_params = Vec::new();
865	        if !signature.type_parameters.is_empty() {
866	            for parameter in self.rpc.type_parameters(signature.id).await? {
867	                match self.rpc.symbol_of_type(parameter.id).await? {
868	                    Some(symbol) => type_params.push(symbol.name),
869	                    None => type_params.push(self.display(parameter.id).await?),
870	                }
871	            }
872	        }
873	        Ok(Some((type_params, params, return_type)))
874	    }
875	}
