877	/// The checker keys a property named by a symbol `__@<name>@<symbol id>`; the source writes `[Symbol.iterator]` or
878	/// `[brand]`. The id is the checker's and does not belong in an answer.
879	fn property_name(name: &str) -> String {
880	    const WELL_KNOWN: [&str; 15] = [
881	        "iterator",
882	        "asyncIterator",
883	        "hasInstance",
884	        "isConcatSpreadable",
885	        "match",
886	        "matchAll",
887	        "replace",
888	        "search",
889	        "species",
890	        "split",
891	        "toPrimitive",
892	        "toStringTag",
893	        "unscopables",
894	        "dispose",
895	        "asyncDispose",
896	    ];
897	    let Some((symbol, _id)) = name.strip_prefix("__@").and_then(|rest| rest.rsplit_once('@')) else {
898	        return name.to_string();
899	    };
900	    if WELL_KNOWN.contains(&symbol) { format!("[Symbol.{symbol}]") } else { format!("[{symbol}]") }
901	}
902	
903	fn is_destructured(name: &str) -> bool {
904	    name.strip_prefix("__").is_some_and(|rest| !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()))
905	}
906	
907	fn to_u32(count: usize) -> u32 {
908	    u32::try_from(count).unwrap_or(u32::MAX)
909	}
910	
911	fn named(name: String, args: Vec<PropType>) -> PropType {
912	    PropType::Named { name: name.into(), args }
913	}
914	
915	/// The types whose conversion needs nothing but their flags.
916	fn simple(info: &TypeInfo) -> Option<PropType> {
917	    let flags = info.flags;
918	    // `boolean` is the union `false | true` and carries both flags.
919	    if flags & flag::BOOLEAN != 0 {
920	        return Some(PropType::Boolean);
921	    }
922	    let known = [
923	        (flag::ANY, PropType::Any),
924	        (flag::UNKNOWN, PropType::Unknown),
925	        (flag::UNDEFINED, PropType::Undefined),
926	        (flag::NULL, PropType::Null),
927	        (flag::VOID, PropType::Void),
928	        (flag::NEVER, PropType::Never),
929	        (flag::STRING, PropType::String),
930	        (flag::NUMBER, PropType::Number),
931	        (flag::BIG_INT, named("bigint".to_string(), Vec::new())),
932	        (flag::ES_SYMBOL, named("symbol".to_string(), Vec::new())),
933	        (flag::NON_PRIMITIVE, named("object".to_string(), Vec::new())),
934	    ];
935	    known.into_iter().find(|(bit, _)| flags & bit != 0).map(|(_, converted)| converted)
936	}
937	
938	/// A union of converted members: `false | true` is `boolean`, a union inside a union is flattened, a repeated member
939	/// is kept once, and a union of one is that member.
940	fn union_of(converted: Vec<PropType>) -> PropType {
941	    let mut flat = Vec::with_capacity(converted.len());
942	    for member in converted {
943	        match member {
944	            PropType::Union(inner) => flat.extend(inner),
945	            other => flat.push(other),
946	        }
947	    }
948	    let both_booleans = flat.contains(&PropType::BoolLiteral(true)) && flat.contains(&PropType::BoolLiteral(false));
949	    let mut members: Vec<PropType> = Vec::with_capacity(flat.len());
950	    for member in flat {
951	        let member = match member {
952	            PropType::BoolLiteral(_) if both_booleans => PropType::Boolean,
953	            other => other,
954	        };
955	        if !members.contains(&member) {
956	            members.push(member);
957	        }
958	    }
959	    if members.len() == 1 { members.swap_remove(0) } else { PropType::Union(members) }
960	}
961	
962	/// An optional prop's type includes `undefined`; react-docgen-typescript drops it, as does the structural result.
963	pub(crate) fn without_undefined(prop_type: PropType, optional: bool) -> PropType {
964	    match prop_type {
965	        PropType::Union(members) if optional => {
966	            let mut kept: Vec<PropType> = members.into_iter().filter(|m| *m != PropType::Undefined).collect();
967	            if kept.len() == 1 { kept.swap_remove(0) } else { PropType::Union(kept) }
968	        }
969	        other => other,
970	    }
971	}
