/// name) — but a real call site always supplies a concrete DOM element type as
/// `T`, e.g. `React.SVGAttributes<SVGSVGElement>` or `React.HTMLProps<HTMLDivElement>`.
/// Derives the element tag from that argument so these generic forms get the
/// same real, structural HTML-attribute expansion (Full mode) and
/// `notableInherited` treatment (Curated mode) that the concrete forms
/// already get from `html_element_for` alone. Only covers the element types
/// that actually appear as `SVGAttributes`/`HTMLProps` type arguments in
/// practice — falls back to `None` (the prior, safe opaque behavior) for
/// anything not in this list rather than guessing at a tag name that's wrong
/// (e.g. `HTMLAnchorElement`'s real tag is `a`, not a naive strip-and-lowercase
/// of the interface name).
/// The element named by a structured type argument such as `HTMLDivElement` or `globalThis.HTMLAnchorElement`.
pub fn html_element_from_collected(type_arg: &crate::types::CollectedType) -> Option<&'static str> {
    match type_arg {
        crate::types::CollectedType::Named { name, .. } => {
            html_element_from_type_arg(name.rsplit('.').next().unwrap_or(name.as_str()))
        }
        _ => None,
    }
}

/// The element a React attributes type is about, from its arguments: `DetailedHTMLProps<InputHTMLAttributes<T>, T>` names
/// it in its second argument and in the attributes type of its first (`HTMLAttributes<T>` alone says only `div`).
pub fn html_element_from_args(args: &[crate::types::CollectedType]) -> Option<&'static str> {
    use crate::types::CollectedType;
    if let Some(element) = args.iter().find_map(html_element_from_collected) {
        return Some(element);
    }
    args.iter().find_map(|arg| match arg {
        CollectedType::AtFile { inner, .. } => html_element_from_args(std::slice::from_ref(inner)),
        CollectedType::Named { name, args } => {
            html_element_from_args(args).or_else(|| html_element_for(name.rsplit('.').next().unwrap_or(name.as_str())))
        }
        _ => None,
    })
}

/// The HTML tag name a DOM element type argument stands for: `HTMLButtonElement` is `button`, as in
/// `ButtonHTMLAttributes<HTMLButtonElement>`. `None` for a type this table does not know.
pub fn html_element_from_type_arg(type_arg: &str) -> Option<&'static str> {
    match type_arg {
        "HTMLAnchorElement" => Some("a"),
        "HTMLButtonElement" => Some("button"),
        "HTMLDivElement" => Some("div"),
        "HTMLSpanElement" => Some("span"),
        "HTMLFormElement" => Some("form"),
        "HTMLImageElement" => Some("img"),
        "HTMLInputElement" => Some("input"),
        "HTMLLabelElement" => Some("label"),
        "HTMLSelectElement" => Some("select"),
        "HTMLTextAreaElement" => Some("textarea"),
        "HTMLVideoElement" => Some("video"),
        "HTMLAudioElement" => Some("audio"),
        "HTMLParagraphElement" => Some("p"),
        "HTMLUListElement" => Some("ul"),
        "HTMLOListElement" => Some("ol"),
        "HTMLLIElement" => Some("li"),
        "HTMLTableElement" => Some("table"),
        "SVGSVGElement" => Some("svg"),
        "SVGCircleElement" => Some("circle"),
        "SVGPathElement" => Some("path"),
        "SVGRectElement" => Some("rect"),
        "SVGLineElement" => Some("line"),
        "SVGGElement" => Some("g"),
        _ => None,
    }
}

/// React's attribute interfaces that carry props but name no element (`HTMLProps<T>` names one, in its argument): the
/// resolver reads their members from React's own declaration under the HTML attribute mode.
pub fn is_attribute_builtin(bare_name: &str) -> bool {
    matches!(bare_name, "AriaAttributes" | "RefAttributes")
}

/// The `@types/react` function-component types, whose first type argument is the props. The one list the extractor
/// and the resolver both read, so a name added here is recognised by both.
pub const FC_FAMILY_TYPE_NAMES: &[&str] = &["FC", "FunctionComponent", "VFC", "VoidFunctionComponent", "ComponentType"];

/// Types that are terminal — never need further resolution.
///
/// These are React-specific type names that we recognize as builtins and don't
/// attempt to chase through imports.
///
/// `extra` allows callers (e.g. the resolver) to pass additional builtin names
/// from `PipelineOptions.extra_builtins` without needing to change this file.
pub fn is_react_builtin(name: &str, extra: &rustc_hash::FxHashSet<compact_str::CompactString>) -> bool {
    extra.contains(name)
        || FC_FAMILY_TYPE_NAMES.contains(&name)
        || matches!(
            name,
            "ReactNode"
                | "ReactElement"
                | "JSX.Element"
                | "CSSProperties"
                | "CSSObject"
                | "SyntheticEvent"
                | "MouseEvent"
                | "KeyboardEvent"
                | "ChangeEvent"
                | "FocusEvent"
                | "FormEvent"
                | "DragEvent"
                | "TouchEvent"
                | "WheelEvent"
                | "AnimationEvent"
                | "TransitionEvent"
                | "ClipboardEvent"
                | "CompositionEvent"
                | "MouseEventHandler"
                | "KeyboardEventHandler"
                | "ChangeEventHandler"
    for field in fields {
        if let Some(key) = &field.index_key {
            key.visit(f);
        }
        field.prop_type.visit(f);
    }
}

/// A signature's `<T>(a: A, b?: B)`, as TypeScript prints it before `=>` or `:`.
fn signature_head(type_params: &[std::string::String], params: &[FunctionParam]) -> std::string::String {
    let type_params =
        if type_params.is_empty() { std::string::String::new() } else { format!("<{}>", type_params.join(", ")) };
    let params = params.iter().enumerate().map(|(i, p)| p.signature(i)).collect::<Vec<_>>().join(", ");
    format!("{type_params}({params})")
}

fn element_to_type_name(element: &str) -> &'static str {
    match element {
        "button" => "Button",
        "input" => "Input",
        "textarea" => "Textarea",
        "select" => "Select",
        "a" => "Anchor",
        "form" => "Form",
        "label" => "Label",
        "img" => "Img",
        _ => "HTML",
    }
}

/// Whether `name` can appear bare as an object-type field key in TypeScript
/// source (`{ name: T }`) or must be quoted (`{ 'name': T }`) — e.g. CSS custom
/// property names (`--accent`) and dashed HTML attributes (`data-testid`).
fn is_valid_identifier(name: &str) -> bool {
    let mut chars = name.chars();
    let Some(first) = chars.next() else { return false };
    (first.is_alphabetic() || first == '_' || first == '$')
        && chars.all(|c| c.is_alphanumeric() || c == '_' || c == '$')
}

