        "HTMLAttributes" | "DOMAttributes" | "HTMLProps" | "AllHTMLAttributes" | "SVGAttributes" | "SVGProps" => {
            let mut arguments = self.rpc.type_arguments(info.id).await?;
            while arguments.last().is_some_and(|argument| argument.is_this_type) {
                arguments.pop();
