        let member = shared("Unions", "wide", "/members/0/fields/1/propType");
        assert_eq!(member["kind"], "object", "{how}");
        for index in 1..12 {
            assert_eq!(shared("Unions", "wide", &format!("/members/{index}/fields/1/propType")), member, "{how}");
        }

