import json,sys
d=json.load(sys.stdin)
props=d['props']
def short(t):
    k=t.get('kind')
    if k=='object': return 'object{'+','.join(f['name'] for f in t['fields'][:6])+(',...' if len(t['fields'])>6 else '')+'}('+str(len(t['fields']))+')'
    if k in('union','intersection'): return k+'['+' | '.join(short(m) for m in t['members'])+']'
    if k=='named': return 'named '+t['name']+'<'+','.join(short(a) for a in t['args'])+'>'
    if k=='htmlAttributes': return 'html:'+t['element']+str(t['omitted'])
    if k=='truncated': return 'TRUNC '+t['text']+str(t['limit'])
    if k=='stringLiteral': return repr(t.get('value'))
    if k=='array': return 'array<'+short(t['element'])+'>'
    return k
for key,c in d['components'].items():
    print('##',c['displayName'])
    ids=c['props'] if isinstance(c['props'],list) else list(c['props'].values())
    for pid in ids:
        p=props[pid] if not isinstance(pid,dict) else pid
        print('  ',p['name'],'=>',short(p['type']))

