import json, sys, collections
a = json.load(open(sys.argv[1])); b = json.load(open(sys.argv[2]))
def flat(d, c):
    m = {}
    for sid in c['props']:
        m.update(d['propSets'][sid])
    return {n: d['props'][pid] for n, pid in m.items()}
def short(t, depth=0):
    k = t.get('kind')
    if k == 'object': return 'object(%d)' % len(t['fields'])
    if k in ('union', 'intersection'): return k + '[' + ' | '.join(short(m) for m in t['members']) + ']'
    if k == 'named': return 'named ' + t['name'] + '<' + ','.join(short(x) for x in t['args']) + '>'
    if k == 'htmlAttributes': return 'html:' + t['element']
    if k == 'truncated': return 'TRUNC ' + t['text'] + str(t['limit'])
    if k == 'array': return 'array<' + short(t['element']) + '>'
    if k == 'function': return 'fn'
    return k
print('components', len(a['components']), len(b['components']))
n = 0
kinds = collections.Counter()
shown = 0
for key, c in a['components'].items():
    cb = b['components'].get(key)
    if cb is None: print('missing', key); continue
    fa, fb = flat(a, c), flat(b, cb)
    for name in sorted(set(fa) | set(fb)):
        if json.dumps(fa.get(name), sort_keys=True) != json.dumps(fb.get(name), sort_keys=True):
            n += 1
            ta = fa.get(name, {}).get('type'); tb = fb.get(name, {}).get('type')
            kinds[(short(ta)[:60] if ta else None, short(tb)[:60] if tb else None)] += 1
            if shown < 12:
                shown += 1
                print(c['displayName'], name, '\n   BASE', short(ta)[:300], '\n   MINE', short(tb)[:300])
print('differing props', n)
for (x, y), cnt in kinds.most_common(15): print(cnt, x, '=>', y)
print('diagnostics equal', a['diagnostics'] == b['diagnostics'])

